import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  delayRender,
  continueRender,
  Img,
} from '../remotionShim';
// Native FontFace loading helper for Malloy Custom Brand Fonts
if (typeof document !== "undefined") {
  const loadCustomFont = (family: string, url: string) => {
    const handle = delayRender(`Loading ${family}`);
    const format = url.endsWith(".otf")
      ? "opentype"
      : url.endsWith(".woff2")
      ? "woff2"
      : url.endsWith(".woff")
      ? "woff"
      : "truetype";
    const font = new FontFace(family, `url('${url}') format('${format}')`);
    font
      .load()
      .then(() => {
        document.fonts.add(font);
        continueRender(handle);
      })
      .catch((err) => {
        console.error(`Error loading custom font ${family}:`, err);
        continueRender(handle);
      });
  };

  loadCustomFont(
    "SFPRODISPLAYBOLD",
    "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/brand_guidelines/fonts/143a40772ee54661a6425da3ce064c41.OTF"
  );
}

// Inline schema representing all customizable parameters


export type KeynoteInfographicProps = Record<string, any>;

// Detailed path coordinates
const growthPathPoints = [
  { x: 0.18, y: 0.65, label: "Year 1" },
  { x: 0.34, y: 0.60, label: "Year 2" },
  { x: 0.50, y: 0.52, label: "Year 3" },
  { x: 0.66, y: 0.43, label: "Year 4" },
  { x: 0.82, y: 0.35, label: "Year 5" },
];

const KeynoteInfographic: React.FC<KeynoteInfographicProps> = ({
  backgroundColor = "#0B0B0B",
  transparentBackground = false,
  durationInSeconds = 12,
  accentColor = "#007aff",
  titleText = "5 Years of Cold Outbound",
  titleFontFamily = "SFPRODISPLAYBOLD",
  subtitleText = "Helping startups scale from early-stage to billion-dollar enterprises.",
  subtitleFontFamily = "SFPRODISPLAYBOLD",
  companyLogos = [
    "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=120&auto=format&fit=crop&q=60",
    "https://images.unsplash.com/photo-1618005198143-e5283b519a7f?w=120&auto=format&fit=crop&q=60",
    "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=120&auto=format&fit=crop&q=60",
    "https://images.unsplash.com/photo-1618005198143-e5283b519a7f?w=120&auto=format&fit=crop&q=60",
    "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=120&auto=format&fit=crop&q=60",
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const tTitleStart = 0;
  const tTitleEnd = 25;

  const tGraphStart = 30;
  const tGraphEnd = 100;

  // Header fade/slide
  const titleAlpha = interpolate(frame, [tTitleStart, tTitleEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(frame, [tTitleStart, tTitleEnd], [-15, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Graph progress
  const graphProgress = interpolate(
    frame,
    [tGraphStart, tGraphEnd],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Smooth Curve Builder
  const buildSmoothCurve = (prog: number) => {
    if (prog <= 0) return "";
    const computedPoints = growthPathPoints.map((pt) => ({
      x: pt.x * width,
      y: pt.y * height,
    }));

    let path = `M ${computedPoints[0].x} ${computedPoints[0].y}`;
    const limit = (computedPoints.length - 1) * prog;
    const index = Math.floor(limit);
    const fract = limit - index;

    for (let i = 1; i <= index; i++) {
      const prev = computedPoints[i - 1];
      const curr = computedPoints[i];
      const cpX1 = prev.x + (curr.x - prev.x) * 0.5;
      const cpY1 = prev.y;
      const cpX2 = prev.x + (curr.x - prev.x) * 0.5;
      const cpY2 = curr.y;
      path += ` C ${cpX1} ${cpY1}, ${cpX2} ${cpY2}, ${curr.x} ${curr.y}`;
    }

    if (fract > 0 && index < computedPoints.length - 1) {
      const prev = computedPoints[index];
      const curr = computedPoints[index + 1];
      const nextX = prev.x + (curr.x - prev.x) * fract;
      const nextY = prev.y + (curr.y - prev.y) * fract;
      const cpX1 = prev.x + (nextX - prev.x) * 0.5;
      const cpY1 = prev.y;
      const cpX2 = prev.x + (nextX - prev.x) * 0.5;
      const cpY2 = nextY;
      path += ` C ${cpX1} ${cpY1}, ${cpX2} ${cpY2}, ${nextX} ${nextY}`;
    }
    return path;
  };

  const smoothCurvePath = buildSmoothCurve(graphProgress);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        overflow: "hidden",
        color: "#ffffff",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "flex-start",
        paddingTop: height * 0.05,
      }}
    >
      {/* Background Ambient Glow */}
      <div
        style={{
          position: "absolute",
          width: width * 0.7,
          height: height * 0.7,
          left: width * 0.15,
          top: height * 0.15,
          borderRadius: "50%",
          background: `radial-gradient(circle, ${accentColor}1F 0%, rgba(0,0,0,0) 70%)`,
          pointerEvents: "none",
          filter: "blur(70px)",
          transform: "none",
          transition: "none",
        }}
      />

      {/* Grid Pattern Behind Everything */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          opacity: 0.15,
          pointerEvents: "none",
          backgroundImage: `linear-gradient(to right, rgba(255,255,255,0.1) 1px, transparent 1px), linear-gradient(to bottom, rgba(255,255,255,0.1) 1px, transparent 1px)`,
          backgroundSize: "60px 60px",
          maskImage: "radial-gradient(circle, black 40%, transparent 80%)",
          WebkitMaskImage: "radial-gradient(circle, black 40%, transparent 80%)",
          transition: "none",
        }}
      />

      {/* Header Block */}
      <div
        style={{
          opacity: titleAlpha,
          transform: `translateY(${titleY}px)`,
          textAlign: "center",
          zIndex: 50,
          transition: "none",
          width: "80%",
        }}
      >
        <h1
          style={{
            fontFamily: titleFontFamily,
            fontSize: height * 0.05,
            fontWeight: "bold",
            margin: 0,
            letterSpacing: "-0.03em",
            color: "#ffffff",
          }}
        >
          <span style={{ color: accentColor }}>5 Years</span> of Cold Outbound
        </h1>
        <p
          style={{
            fontFamily: subtitleFontFamily,
            fontSize: height * 0.018,
            color: "rgba(255, 255, 255, 0.65)",
            marginTop: height * 0.012,
            fontWeight: "normal",
            letterSpacing: "-0.01em",
            maxWidth: "600px",
            marginLeft: "auto",
            marginRight: "auto",
          }}
        >
          {subtitleText}
        </p>
      </div>

      {/* Background Grid Lines & SVG Paths */}
      <svg
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          pointerEvents: "none",
          zIndex: 10,
        }}
      >
        {/* Render Graph Area Fill Gradient */}
        {smoothCurvePath && (
          <path
            d={`${smoothCurvePath} L ${
              growthPathPoints[Math.min(
                growthPathPoints.length - 1,
                Math.floor(graphProgress * (growthPathPoints.length - 1))
              )].x *
              width
            } ${height * 0.72} L ${growthPathPoints[0].x * width} ${
              height * 0.72
            } Z`}
            fill={`url(#areaGradient)`}
            opacity={0.15}
            style={{ transition: "none" }}
          />
        )}

        <defs>
          <linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={accentColor} />
            <stop offset="100%" stopColor="transparent" />
          </linearGradient>
        </defs>

        {/* Vertical Dashed Projection lines */}
        {growthPathPoints.map((pt, i) => {
          const ptTrigger = tGraphStart + i * 15;
          const lineAlpha = interpolate(frame, [ptTrigger, ptTrigger + 20], [0, 0.45], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          return (
            <line
              key={i}
              x1={pt.x * width}
              y1={pt.y * height}
              x2={pt.x * width}
              y2={height * 0.72}
              stroke="rgba(255, 255, 255, 0.25)"
              strokeDasharray="4 4"
              strokeWidth={1.5}
              opacity={lineAlpha}
              style={{ transition: "none" }}
            />
          );
        })}

        {/* Main Growing Solid Accent Curve */}
        {smoothCurvePath && (
          <path
            d={smoothCurvePath}
            fill="none"
            stroke={accentColor}
            strokeWidth={5}
            strokeLinecap="round"
            style={{ transition: "none" }}
          />
        )}
      </svg>

      {/* Main Graph Highlight Nodes & Year Labels */}
      {growthPathPoints.map((pt, i) => {
        const appearFrame = tGraphStart + i * 15;
        const nodeScale = spring({
          frame: frame - appearFrame,
          fps,
          config: { damping: 13, mass: 0.6, stiffness: 100 },
        });

        const textOpacity = interpolate(
          frame,
          [appearFrame + 5, appearFrame + 20],
          [0, 1],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        const textY = interpolate(
          frame,
          [appearFrame, appearFrame + 15],
          [10, 0],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        // Logo animations synced with each year node
        const logoSpring = spring({
          frame: frame - (appearFrame + 10),
          fps,
          config: { damping: 12, mass: 0.5, stiffness: 110 },
        });

        if (frame < appearFrame) return null;

        return (
          <React.Fragment key={i}>
            {/* Inner Ring Glow */}
            <div
              style={{
                position: "absolute",
                left: pt.x * width - 14,
                top: pt.y * height - 14,
                width: 28,
                height: 28,
                borderRadius: "50%",
                backgroundColor: `${accentColor}1A`,
                border: `1px solid ${accentColor}33`,
                transform: `scale(${nodeScale})`,
                zIndex: 30,
                pointerEvents: "none",
                transition: "none",
              }}
            />

            {/* Visual Node */}
            <div
              style={{
                position: "absolute",
                left: pt.x * width - 7,
                top: pt.y * height - 7,
                width: 14,
                height: 14,
                borderRadius: "50%",
                backgroundColor: "#ffffff",
                border: `3px solid ${accentColor}`,
                boxShadow: `0 0 14px ${accentColor}`,
                transform: `scale(${nodeScale})`,
                zIndex: 35,
                transition: "none",
              }}
            />

            {/* Year Label Below the Node */}
            <div
              style={{
                position: "absolute",
                left: pt.x * width - 50,
                top: pt.y * height + 18,
                width: 100,
                textAlign: "center",
                fontFamily: titleFontFamily,
                fontSize: height * 0.016,
                color: "rgba(255, 255, 255, 0.85)",
                opacity: textOpacity,
                transform: `translateY(${textY}px)`,
                zIndex: 35,
                fontWeight: "bold",
                pointerEvents: "none",
                transition: "none",
                textShadow: "0px 2px 4px rgba(0,0,0,0.5)",
              }}
            >
              {pt.label}
            </div>

            {/* Company Logo Card (placed strategically in vertical empty space above corresponding node) */}
            {companyLogos[i] && (
              <div
                style={{
                  position: "absolute",
                  left: pt.x * width - 35,
                  top: pt.y * height - 85,
                  width: 70,
                  height: 48,
                  backgroundColor: "rgba(20, 20, 20, 0.8)",
                  borderRadius: "8px",
                  border: "1px solid rgba(255, 255, 255, 0.15)",
                  boxShadow: "0px 10px 25px rgba(0, 0, 0, 0.4)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  padding: "6px",
                  transform: `scale(${logoSpring})`,
                  opacity: logoSpring,
                  zIndex: 40,
                  transition: "none",
                  backdropFilter: "blur(4px)",
                }}
              >
                <Img
                  src={companyLogos[i]}
                  style={{
                    maxWidth: "100%",
                    maxHeight: "100%",
                    objectFit: "contain",
                    borderRadius: "4px",
                    filter: "grayscale(20%) contrast(110%)",
                  }}
                />
              </div>
            )}
          </React.Fragment>
        );
      })}
    </AbsoluteFill>
  );
};

export default KeynoteInfographic;